import 'dart:io';
import 'package:drift/drift.dart';
import 'package:drift/native.dart';
part 'app_database.g.dart';
class Users extends Table { TextColumn get id=>text()(); TextColumn get email=>text().unique()(); IntColumn get monthlyIncome=>integer()(); IntColumn get initialBalance=>integer()(); IntColumn get startDay=>integer()(); TextColumn get timezone=>text()(); DateTimeColumn get createdAt=>dateTime()(); @override Set<Column> get primaryKey=>{id}; }
class Categories extends Table { TextColumn get id=>text()(); TextColumn get userId=>text()(); TextColumn get name=>text()(); TextColumn get type=>text()(); TextColumn get iconColor=>text()(); BoolColumn get isHidden=>boolean()(); BoolColumn get isDefault=>boolean()(); @override Set<Column> get primaryKey=>{id}; @override List<Set<Column>> get uniqueKeys=>[{userId,name,type}]; }
class Transactions extends Table { TextColumn get id=>text()(); TextColumn get userId=>text()(); TextColumn get categoryId=>text()(); TextColumn get type=>text()(); IntColumn get amount=>integer()(); DateTimeColumn get localDate=>dateTime()(); DateTimeColumn get occurredAt=>dateTime()(); TextColumn get note=>text().nullable()(); DateTimeColumn get updatedAt=>dateTime()(); DateTimeColumn get deletedAt=>dateTime().nullable()(); @override Set<Column> get primaryKey=>{id}; @override List<Index> get indexes=>[Index('transactions_user_local_date','CREATE INDEX transactions_user_local_date ON transactions (user_id, local_date)')]; }
class Goals extends Table { TextColumn get id=>text()(); TextColumn get userId=>text()(); TextColumn get name=>text()(); IntColumn get targetAmount=>integer()(); IntColumn get initialAmount=>integer()(); DateTimeColumn get startDate=>dateTime()(); DateTimeColumn get deadline=>dateTime().nullable()(); TextColumn get mode=>text()(); IntColumn get monthlyLimit=>integer()(); TextColumn get status=>text()(); DateTimeColumn get updatedAt=>dateTime()(); DateTimeColumn get deletedAt=>dateTime().nullable()(); @override Set<Column> get primaryKey=>{id}; }
class GoalSnapshots extends Table { TextColumn get goalId=>text()(); DateTimeColumn get snapshotDate=>dateTime()(); IntColumn get accumulated=>integer()(); DateTimeColumn get projectedDate=>dateTime().nullable()(); @override Set<Column> get primaryKey=>{goalId,snapshotDate}; }
class Entitlements extends Table { TextColumn get id=>text()(); TextColumn get userId=>text().unique()(); TextColumn get plan=>text()(); DateTimeColumn get expiresAt=>dateTime().nullable()(); @override Set<Column> get primaryKey=>{id}; }
@DriftDatabase(tables:[Users,Categories,Transactions,Goals,GoalSnapshots,Entitlements])
class AppDatabase extends _$AppDatabase { AppDatabase({QueryExecutor? executor}):super(executor??NativeDatabase(File('gop_lua.sqlite'))); @override int get schemaVersion=>1; }
